def format_bytes(n):
    """Return a human-readable byte size string, e.g. '1.5 KB'."""
    units = ['B', 'KB', 'MB', 'GB', 'TB']
    size = n
    for unit in units[:-1]:
        if size < 1024:
            break
        size /= 1024
    return f"{size:.1f} {unit}"
